import{_ as t,o as l,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Developer Monthly | 2025-04-02 | Part 2","description":"","frontmatter":{"title":"Ceph Developer Monthly | 2025-04-02 | Part 2","date":"2025-04-02T00:00:00.000Z","updated":"2025-04-03T00:00:00.000Z","tags":["Ceph","CI测试","Clang-Tidy","RGW","OpenTelemetry"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Monthly_2025-04-02_Part_2.md","filePath":"posts/2025/Ceph_Developer_Monthly_2025-04-02_Part_2.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Ceph_Developer_Monthly_2025-04-02_Part_2.md"};function n(i,e,s,_,c,h){return l(),a("div",null,[...e[0]||(e[0]=[r('<p>本次Ceph开发者月度会议主要讨论了以下几个方面：</p><h3 id="_1-ci测试优化" tabindex="-1">1. CI测试优化 <a class="header-anchor" href="#_1-ci测试优化" aria-label="Permalink to &quot;1. CI测试优化&quot;">​</a></h3><ul><li><strong>讨论内容</strong>：针对<code>make check</code>测试的运行时间和测试范围进行了讨论。当前测试运行时间较长且不稳定，开发人员建议将快速单元测试限制在15-20分钟内，将更复杂的测试移至单独的长时间运行任务中。</li><li><strong>关键点</strong>：快速单元测试应避免成为合并PR的阻碍，长时间运行测试可作为全局门控任务，按需触发。</li><li><strong>决定事项</strong>：尚未达成共识，需进一步讨论。</li></ul><h3 id="_2-clang-tidy静态代码分析" tabindex="-1">2. Clang-Tidy静态代码分析 <a class="header-anchor" href="#_2-clang-tidy静态代码分析" aria-label="Permalink to &quot;2. Clang-Tidy静态代码分析&quot;">​</a></h3><ul><li><strong>讨论内容</strong>：在CI中引入Clang-Tidy静态代码分析工具，用于检测代码中的潜在问题。该工具已在RGW和OSD代码库中进行了初步测试，并发现了一些实际问题。</li><li><strong>关键点</strong>：Clang-Tidy运行时间已优化，但可能因PR的文件数量而有所不同。</li><li><strong>决定事项</strong>：将在基础设施团队会议上进一步讨论，并考虑先添加为非必选检查。</li></ul><h3 id="_3-rgw-tentacle发布计划" tabindex="-1">3. RGW Tentacle发布计划 <a class="header-anchor" href="#_3-rgw-tentacle发布计划" aria-label="Permalink to &quot;3. RGW Tentacle发布计划&quot;">​</a></h3><ul><li><strong>讨论内容</strong>：讨论了RGW Tentacle版本的发布计划，确认了哪些功能将包含在此次发布中，并评估了各功能的完成进度。</li><li><strong>关键点</strong>：数据日志异步修复、CRC64校验、对象恢复等功能已确认，D4N的特性分支可能无法在此次发布中完成。</li><li><strong>决定事项</strong>：将在后续的RGW会议或Slack中跟进，确保所有功能按时完成。</li></ul><h3 id="_4-opentelemetry升级" tabindex="-1">4. OpenTelemetry升级 <a class="header-anchor" href="#_4-opentelemetry升级" aria-label="Permalink to &quot;4. OpenTelemetry升级&quot;">​</a></h3><ul><li><strong>讨论内容</strong>：讨论了Ceph使用的OpenTelemetry CPP库的升级问题。当前版本存在一些问题，阻碍了Ceph的进一步开发。需要社区帮助决定如何替换旧的Jagger exporter，并选择合适的替代方案。</li><li><strong>关键点</strong>：需要社区帮助做出技术决策，特别是关于tracing exporter的选择。</li><li><strong>决定事项</strong>：将在CSC会议和邮件列表中进一步讨论，寻求社区意见。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ol><li>CI测试优化：继续讨论<code>make check</code>的运行时间和范围，寻找平衡点。</li><li>Clang-Tidy静态代码分析：在基础设施团队会议上讨论，并考虑先添加为非必选检查。</li><li>RGW Tentacle发布计划：在RGW会议或Slack中跟进，确认各功能的进度。</li><li>OpenTelemetry升级：在CSC会议和邮件列表中讨论，寻求社区意见，特别是关于tracing exporter的选择。</li></ol>',11)])])}const g=t(o,[["render",n]]);export{d as __pageData,g as default};
